#[cfg(test)]
mod tests {
    use rigorix_engine::capacity_ledger::domain::{Exposure, ResourceId, Window};

    #[test]
    fn test_exposure_is_defined() {
        let e = Exposure::new(ResourceId::new("gpu"), 10, 4, 3, Window::bounded(60));
        assert_eq!(e.hard_limit, 10);
        assert_eq!(e.committed, 4);
        assert_eq!(e.outstanding, 3);
        // committed and outstanding stay separate — never collapsed into one total.
        assert_ne!(e.committed, e.outstanding);
        assert_eq!(e.available(), 3);
    }

    #[test]
    fn test_exposure_interacts_with_reservation() {
        // Over-commit safety: available saturates at zero, never underflows.
        let over = Exposure::new(ResourceId::new("gpu"), 5, 4, 4, Window::UNBOUNDED);
        assert_eq!(over.available(), 0);

        let full = Exposure::new(ResourceId::new("gpu"), 5, 5, 0, Window::UNBOUNDED);
        assert_eq!(full.available(), 0);
    }

    #[test]
    fn test_exposure_capacity_queries() {
        let e = Exposure::new(ResourceId::new("gpu"), 10, 4, 3, Window::UNBOUNDED);
        assert!(e.would_fit(3));
        assert!(!e.would_fit(4));
        assert!(!e.is_exhausted());
        assert!(e.is_consistent());
        assert!((e.claimed_ratio() - 0.7).abs() < f64::EPSILON);

        let exhausted = Exposure::new(ResourceId::new("gpu"), 10, 6, 4, Window::UNBOUNDED);
        assert!(exhausted.is_exhausted());
        assert!(!exhausted.would_fit(1));

        // An over-claimed snapshot is detectable, not silently accepted.
        let inconsistent = Exposure::new(ResourceId::new("gpu"), 5, 4, 4, Window::UNBOUNDED);
        assert!(!inconsistent.is_consistent());
        assert_eq!(inconsistent.claimed_ratio(), 1.0);
    }
}
